export function treeOfThoughtsReasoning(input, evaluate, backtrack) {
  const branches = [];
  function explore(node) {
    const childNodes = evaluate(node);
    if (childNodes.length === 0) {
      return node;
    }
    branches.push(...childNodes);
    for (const child of childNodes) {
      explore(child);
    }
  }
  explore(input);
  return backtrack(branches);
}